SELECT business, business_name,
       COUNT(*) AS row_count,
       MAX(day) AS last_day,
       MIN(source_table) AS sample_source_table
FROM names
WHERE CAST(business_name AS VARCHAR) NOT IN ('', '\\N', '\N', 'nan', 'NaN', 'None', '<NA>')
GROUP BY business, business_name
ORDER BY business, row_count DESC, last_day DESC